window.SIGA_QUESTION_BANKS={"employee":[{"id":1,"mode":"binary","text":"تستعد جهة عملك للدخول في شراكة مع جهة أخرى، وعُرض عليك تولي جانب واحد فقط قبل اعتمادها؛ فأيهما تفضل؟","options":[{"text":"دراسة بنود الشراكة، ومقارنة التزامات الطرفين ومكاسبهما، والكشف عن الافتراضات أو المخاطر التي قد تؤثر في جدواها.","code":"(A التحليلي)"},{"text":"تحويل بنود الشراكة المتفق عليها إلى مراحل ومواعيد محددة، وتوزيع المسؤوليات، وإعداد وسائل متابعة تنفيذ الالتزامات.","code":"(B التنفيذي)"}],"meta":{"indicator":"هيرمان"}},{"id":2,"mode":"binary","text":"عند استلام قيادة فريق جديد، فإن أول ما أركز عليه غالبًا هو:","options":[{"text":"وضع اتجاه واضح للعمل، وتحديد مسؤوليات كل عضو في الفريق.","code":"(D الهيمنة)"},{"text":"بناء علاقة إيجابية مع الفريق، وتحفيزهم للعمل بروح واحدة.","code":"(I التأثير)"}],"meta":{"indicator":"ديسك"}},{"id":3,"mode":"binary","text":"في يوم إجازتي، إذا كان لدي عمل شخصي يمكن تأجيله دون أن يترتب على ذلك ضرر، وفي الوقت نفسه تتاح لي فرصة لنشاط أستمتع به، فإنني غالبًا:","options":[{"text":"أستفيد من وقت الإجازة وأشارك في النشاط، وأؤجل العمل إلى وقت آخر مناسب.","code":"الاستمتاع بالحياة"},{"text":"أفضّل إنجاز العمل في الوقت الذي خططت له، حتى لو فاتتني فرصة النشاط هذه المرة.","code":"الانضباط والالتزام"}],"meta":{"indicator":"القيم"}},{"id":4,"mode":"binary","text":"حدث خلاف بين شخصين في جهة عملك، وعُرض عليك تولي دور واحد فقط في معالجته؛ فأيهما تفضل؟","options":[{"text":"تحليل وقائع الخلاف وأسبابه، ومقارنة المعلومات المتاحة؛ للوصول إلى تفسير موضوعي لما حدث، دون تولّي مهمة الإصلاح بين الطرفين.","code":"(A التحليلي)"},{"text":"الاستماع إلى الطرفين، وفهم مشاعرهما واحتياجاتهما، ومساعدتهما على استعادة الحوار والتفاهم.","code":"(C العاطفي)"}],"meta":{"indicator":"هيرمان"}},{"id":5,"mode":"binary","text":"عند اكتشاف خطأ أثناء تنفيذ العمل، فإن الخيار الأقرب إلى طريقتي هو:","options":[{"text":"اتخاذ إجراء فوري لمعالجة الخطأ وضمان استمرار العمل.","code":"(D الهيمنة)"},{"text":"تحديد سبب الخطأ بدقة، وتصحيح مساره حتى لا يتكرر لاحقًا.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":6,"mode":"binary","text":"إذا كان أمامي في الوقت نفسه مشروعان متقاربان في الجهد والوقت؛ أحدهما يحقق لي عائدًا ماليًا ومصلحة شخصية أكبر، والآخر يحقق نفعًا مباشرًا لأشخاص يمكنهم الاستفادة منه، فإنني غالبًا:","options":[{"text":"أختار المشروع الذي يحقق لي العائد والمصلحة الشخصية الأكبر.","code":"المادية"},{"text":"أختار المشروع الذي يحقق فائدة وأثرًا أكبر للآخرين.","code":"العطاء"}],"meta":{"indicator":"القيم"}},{"id":7,"mode":"binary","text":"إذا كُلِّفت بقيادة مشروع جديد يشارك فيه عدد من الأشخاص، فأي الأسلوبين تفضل؟","options":[{"text":"أضع الخطة، وأقود المشروع من خلال مشاركتي المباشرة في تنفيذ أعماله الأساسية حتى ينطلق كما أريد.","code":"المقاتل المنفرد"},{"text":"أجتمع بالفريق، وأشركهم في وضع الخطة، وأحفزهم على تنفيذها معًا.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":8,"mode":"binary","text":"عُرض عليك موضوع استخدام الذكاء الاصطناعي في بيئة العمل، وطُلب منك إعداد دراسة واحدة له؛ فأيهما تفضل؟","options":[{"text":"تقسيم الموضوع إلى عناصر، ودراسة تفاصيله، وتحديد أسباب استخدامه والنتائج المترتبة عليه.","code":"(A التحليلي)"},{"text":"تكوين صورة شاملة لكيف يمكن أن يغيّر الذكاء الاصطناعي طبيعة الأعمال والمهارات المطلوبة والخدمات المقدمة مستقبلًا.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":9,"mode":"binary","text":"عند تقديم فكرة جديدة أمام الآخرين، فإن ما ينسجم مع طريقتي غالبًا هو:","options":[{"text":"عرض الفكرة بأسلوب مؤثر يجذب اهتمام الآخرين ويزيد قابليتهم لتأييدها.","code":"(I التأثير)"},{"text":"ترتيب الفكرة بصورة منطقية واضحة تساعد الآخرين على فهمها وتحويلها إلى خطوات قابلة للتطبيق.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":10,"mode":"binary","text":"عندما أعمل على مهمة في غاية الأهمية وأصل فيها إلى مستوى جيد، ثم أجد أن الوصول إلى مستوى متميز يحتاج مني إلى وقت وجهد إضافيين، وفي الوقت نفسه يوجد شخص قريب مني يحتاج إلى وقتي ومساندتي، فإنني غالبًا:","options":[{"text":"أركز على إكمال المهمة بالمستوى المتميز الذي أطمح إليه، ثم أخصص وقتي للمساعدة بعد ذلك.","code":"الإنجاز والإتقان"},{"text":"أكتفي بالمستوى الجيد في المهمة، وأخصص جزءًا من وقتي لمساندة الشخص الذي يحتاج إليّ.","code":"الرعاية والرحمة"}],"meta":{"indicator":"القيم"}},{"id":11,"mode":"binary","text":"لديك وقت محدود لتعلّم استخدام برنامج جديد فأي الطريقتين أدناه تفضل؟","options":[{"text":"اتباع دليل تدريبي مرتب، وإتقان خطوات الاستخدام الأساسية بالتسلسل.","code":"(B التنفيذي)"},{"text":"تجربة البرنامج مباشرة، واستكشاف خصائصه وطرق استخدامه بحرية.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":12,"mode":"binary","text":"عندما يحتاج النقاش في الاجتماع إلى توجيه، فإن تركيزي يتجه غالبًا إلى:","options":[{"text":"قيادة النقاش نحو قرار واضح، وتحديد ما يلزم تنفيذه بعد الاجتماع.","code":"(D الهيمنة)"},{"text":"تنشيط الحوار، وتشجيع الحضور على المشاركة وطرح آرائهم بثقة.","code":"(I التأثير)"}],"meta":{"indicator":"ديسك"}},{"id":13,"mode":"binary","text":"عندما أكون مقتنعًا بفكرة مهمة، ويعارضها أشخاص أحتاج إلى تعاونهم، فإنني غالبًا:","options":[{"text":"أواصل محاولة إقناعهم وتغيير موقفهم حتى أكسب تأييدهم للفكرة.","code":"التأثير والنفوذ"},{"text":"أتقبل بقاءهم على رأي مختلف، وأتعامل معهم باحترام دون أن أرى ضرورة لتغيير موقفهم.","code":"التسامح وتقبّل الآخرين"}],"meta":{"indicator":"القيم"}},{"id":14,"mode":"binary","text":"إذا استعديت لاختبار مهم، ولم يتبقَّ سوى وقت محدود للمراجعة، فأيهما أقرب إلى طريقتك؟","options":[{"text":"أفضل أن أسير وفق خطة مراجعة أضعها لنفسي حتى أصل إلى أفضل نتيجة.","code":"المقاتل المنفرد"},{"text":"أنظم جلسة مراجعة مع زملائي، وأشجعهم على التعاون حتى نستفيد جميعًا.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":15,"mode":"binary","text":"أرادت جهة عملك تطوير إحدى خدماتها، وعُرض عليك الانضمام إلى فريق واحد فقط؛ فأيهما تختار؟","options":[{"text":"فريق يصنف ملاحظات المستفيدين ويحلل تكرارها والعلاقات بينها؛ لتحديد المشكلات الأكثر تأثيرًا.","code":"(A التحليلي)"},{"text":"فريق يلتقي بالمستفيدين ويستمع إلى تجاربهم واحتياجاتهم؛ لفهم ما يتوقعونه من الخدمة.","code":"(C العاطفي)"}],"meta":{"indicator":"هيرمان"}},{"id":16,"mode":"binary","text":"عندما يحدث خلاف بين أعضاء الفريق، فإن تعاملي الأول غالبًا يكون في:","options":[{"text":"حسم الموقف وتوجيه الفريق نحو قرار يحافظ على استمرار العمل.","code":"(D الهيمنة)"},{"text":"تهدئة الموقف وتقريب وجهات النظر حتى يعود التفاهم بين الأعضاء.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":17,"mode":"binary","text":"إذا أتيحت لي فرصتان متقاربتان في المزايا؛ الأولى تمنحني منصبًا أعلى ومكانة أكبر، والثانية أقل مكانة لكنها تتيح لي خدمة الآخرين بصورة مباشرة وتحقيق أثر واضح، فإنني غالبًا:","options":[{"text":"أختار الفرصة التي تمنحني منصبًا أعلى ومجالًا أكبر للتقدم والمكانة.","code":"الطموح والمكانة"},{"text":"أختار الفرصة التي أستطيع من خلالها تقديم خدمة أكبر وتحقيق أثر مباشر، حتى لو كان منصبها أقل.","code":"التواضع والخدمة"}],"meta":{"indicator":"القيم"}},{"id":18,"mode":"binary","text":"عند انضمام موظف جديد إلى فريقك، قُسّمت عملية تهيئته بينك وبين زميلك؛ فأي جانب تفضل توليه؟","options":[{"text":"تعريفه بمهامه وإجراءاته وأدواته، والتأكد من اكتمال متطلبات مباشرته للعمل.","code":"(B التنفيذي)"},{"text":"تعريفه بأعضاء الفريق، وبناء تواصل إيجابي معه، ومساعدته على الشعور بالترحيب والانتماء.","code":"(C العاطفي)"}],"meta":{"indicator":"هيرمان"}},{"id":19,"mode":"binary","text":"إذا أُتيحت للفريق فرصة المشاركة في مبادرة مهمة، وكان موعد التقديم قريبًا، فإن تركيزي يتجه غالبًا إلى:","options":[{"text":"المبادرة باقتناص الفرصة، وقيادة التحرك للاستفادة منها قبل فواتها.","code":"(D الهيمنة)"},{"text":"مراجعة شروط المبادرة ومتطلباتها، والتأكد من جاهزية الفريق قبل التقديم.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":20,"mode":"binary","text":"إذا كان أمامي خياران وظيفيان؛ أحدهما يمنحني فرصة أكبر للتطور وزيادة الدخل لكنه أقل استقرارًا، والآخر أكثر استقرارًا لكن فرص نموه محدودة، فأنا أقرب إلى:","options":[{"text":"اختيار الفرصة التي تمنحني نموًا وخبرة أكبر، حتى لو صاحبها قدر أكبر من المخاطرة وعدم الاستقرار.","code":"التجديد والتطوير"},{"text":"اختيار الوظيفة الأكثر استقرارًا ووضوحًا، حتى لو كانت فرص التطور وزيادة الدخل فيها أقل.","code":"الاستقرار والأمان"}],"meta":{"indicator":"القيم"}},{"id":21,"mode":"binary","text":"إذا كانت الأسرة تستعد لاستقبال مناسبة مهمة تتطلب دقة وتنظيمًا، فأي الخيارين يعبر عنك أكثر؟","options":[{"text":"أحرص على أن أتولى الأعمال الأكثر حساسية حتى تخرج بالمستوى الذي أطمح إليه.","code":"القناص"},{"text":"أوزع الأعمال، وأوجه أفراد الأسرة، وأتابع تنفيذها حتى تظهر بأفضل صورة.","code":"الأستاذ"}],"meta":{"indicator":"الدوافع"}},{"id":22,"mode":"binary","text":"طُلب من فريقين تطوير أسلوب عمل قائم، ويمكنك الانضمام إلى فريق واحد فقط؛ فأيهما تختار؟","options":[{"text":"فريق يراجع خطوات الأسلوب الحالي، ويعيد ترتيبها وتبسيطها؛ ليصبح أكثر تنظيمًا وسهولة في التنفيذ.","code":"(B التنفيذي)"},{"text":"فريق يعيد تصور العمل من أساسه، ويصمم أسلوبًا مختلفًا يمكن أن يغير طريقة تنفيذه.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":23,"mode":"binary","text":"عند التعاون مع أشخاص أتعامل معهم لأول مرة، فإن الأقرب إلى طريقتي هو:","options":[{"text":"المبادرة بالتواصل وكسر الحواجز لبناء علاقة إيجابية بسرعة.","code":"(I التأثير)"},{"text":"منح العلاقة وقتًا كافيًا حتى تتكون الثقة بصورة طبيعية.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":24,"mode":"binary","text":"في مهمة أُعطيت فيها حرية اختيار طريقة التنفيذ، وكان أمامي أسلوب أراه أنسب لي وآخر هو الأسلوب المتعارف عليه في الجهة، فإنني غالبًا:","options":[{"text":"أختار الطريقة التي أراها أنسب وأقرب لأسلوبي، ما دامت تحقق النتيجة المطلوبة.","code":"الاستقلالية"},{"text":"أستخدم الأسلوب المتعارف عليه في الجهة؛ لأن توحيد الطريقة والانسجام مع النظام القائم مهمان بالنسبة لي.","code":"الأصالة والنظام"}],"meta":{"indicator":"القيم"}},{"id":25,"mode":"binary","text":"عند إعداد حملة للتعريف بمبادرة جديدة، عُرض عليك تولي دور واحد فقط؛ فأيهما تفضل؟","options":[{"text":"صياغة الرسالة بما يتناسب مع اهتمامات الجمهور واحتياجاته، وإدارة التواصل والتفاعل معه.","code":"(C العاطفي)"},{"text":"ابتكار مفهوم غير مألوف للحملة، واستخدام صور وتشبيهات تقدم المبادرة من منظور مختلف.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":26,"mode":"binary","text":"عند ملاحظة خطأ في عمل أحد الزملاء، فإن أول ما أحرص عليه غالبًا هو:","options":[{"text":"التعامل معه بهدوء ومساندته في تصحيح الخطأ دون إحراج.","code":"(S الثبات)"},{"text":"تحديد موضع الخطأ بدقة، والتأكد من تصحيحه بالطريقة الصحيحة.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":27,"mode":"binary","text":"عندما أبدأ مهمة معقدة وقد تظهر أثناء تنفيذها معلومات جديدة لم تكن معروفة من البداية، فإنني غالبًا:","options":[{"text":"أبدأ بما هو متاح، وأعدّل طريقة العمل كلما ظهرت معلومات أو مستجدات جديدة.","code":"المرونة والتكيف"},{"text":"أحرص قبل البدء على وضع خطوات واضحة ومتسلسلة للعمل، ثم ألتزم بها قدر الإمكان أثناء التنفيذ.","code":"الالتزام بالمنهج"}],"meta":{"indicator":"القيم"}},{"id":28,"mode":"binary","text":"إذا طُلب منك تنفيذ مبادرة تطوعية تخدم المجتمع، فأي الأسلوبين تفضل؟","options":[{"text":"أبادر بالعمل ميدانيًا، وأكون في مقدمة المنفذين حتى يتحقق الإنجاز.","code":"المقاتل المنفرد"},{"text":"أستقطب المتطوعين، وأوزع الأدوار، وأحفزهم حتى تنجح المبادرة.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":29,"mode":"binary","text":"عند تنظيم فعالية مهمة، عُرض عليك الانضمام إلى لجنة واحدة فقط؛ فأيهما تختار؟","options":[{"text":"لجنة التشغيل التي تنظم البرنامج والتجهيزات والمواعيد، وتتابع تنفيذ الفعالية وفق الخطة.","code":"(B التنفيذي)"},{"text":"لجنة تجربة الحاضرين التي تهتم براحتهم وتفاعلهم، وتهيئ أجواء تشجعهم على التواصل والمشاركة.","code":"(C العاطفي)"}],"meta":{"indicator":"هيرمان"}},{"id":30,"mode":"binary","text":"إذا كان لدي جهاز أو غرض ذو قيمة لا أستخدمه حاليًا، وأعرف أن شخصًا قريبًا مني يحتاج إليه فعلًا، فإنني غالبًا:","options":[{"text":"أحتفظ به؛ لأنني قد أحتاج إليه لاحقًا أو أرى أن الاحتفاظ بما أملكه أفضل من التفريط فيه.","code":"المادية"},{"text":"أعطيه للشخص الذي يحتاج إليه الآن، ما دمت لا أستخدمه ويمكن أن ينتفع به أكثر مني.","code":"العطاء"}],"meta":{"indicator":"القيم"}},{"id":31,"mode":"binary","text":"عندما يزداد ضغط العمل على الفريق، فإن أكثر ما أركز عليه غالبًا هو:","options":[{"text":"المحافظة على هدوء الفريق وتقديم الدعم حتى يستمر العمل بتوازن.","code":"(S الثبات)"},{"text":"ترتيب الأولويات ومتابعة التفاصيل المهمة حتى لا تتأثر جودة العمل.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":32,"mode":"binary","text":"إذا كان أحد أعضاء الفريق مسؤولًا عن جزء مهم من مشروع، ثم مر بظرف شخصي صعب قبل موعد التسليم، فإنني غالبًا:","options":[{"text":"أطلب منه أن يوازن قدر الإمكان بين ظرفه الشخصي ومسؤوليته في إنجاز الجزء المطلوب، بحيث يحافظ على موعد التسليم ومستوى العمل.","code":"الإنجاز والإتقان"},{"text":"أراعي ظرفه الشخصي، وأمنحه مرونة أكبر؛ كأن أؤخر موعد التسليم، أو أخفف عنه بعض المتطلبات، أو أكلف شخصًا آخر بالمهمة إذا رأى أن ذلك أنسب له.","code":"الرعاية والرحمة"}],"meta":{"indicator":"القيم"}},{"id":33,"mode":"binary","text":"إذا حصلت على مبلغ مالي وترغب في استثماره في مشروع صغير، فكيف تفضل أن تبدأ؟","options":[{"text":"أفضل البدء بتنفيذه بنفسي، ثم أستعين بالآخرين إذا احتجت لذلك.","code":"المقاتل المنفرد"},{"text":"أبحث منذ البداية عن شركاء مناسبين، وأبني معهم فريقًا لإنجاح المشروع.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":34,"mode":"binary","text":"بعد انتهاء مشروع مهم، لم يتبقَّ لك وقت إلا لتولي مهمة ختامية واحدة، بينما يتولى زميلك المهمة الأخرى؛ فأيهما تختار؟","options":[{"text":"تحليل مؤشرات المشروع، ومقارنة نتائجه بأهدافه، وتفسير أسباب الفروق التي ظهرت بينهما.","code":"(A التحليلي)"},{"text":"إغلاق المشروع تنظيميًا، والتأكد من اكتمال مهامه ووثائقه، وتسليم مخرجاته، وحصر ما تبقى من إجراءات.","code":"(B التنفيذي)"}],"meta":{"indicator":"هيرمان"}},{"id":35,"mode":"binary","text":"عندما يتم تقديمي في اجتماع رسمي أمام أشخاص لا يعرفونني، فإنني غالبًا:","options":[{"text":"أهتم بذكر مسماي وصفتي وخبرتي؛ لأنها تعكس المستوى والمسؤولية التي وصلت إليها.","code":"الطموح والمكانة"},{"text":"لا أهتم كثيرًا بذكر مسماي أو صفتي؛ فالأهم بالنسبة لي ما أقدمه من دور وخدمة.","code":"التواضع والخدمة"}],"meta":{"indicator":"القيم"}},{"id":36,"mode":"binary","text":"عند حدوث تغيير مفاجئ في الخطة، فإن أولويتي غالبًا تكون في:","options":[{"text":"المبادرة بتوجيه الفريق واتخاذ القرارات اللازمة للانتقال إلى الخطة الجديدة.","code":"(D الهيمنة)"},{"text":"مساعدة الفريق على التكيف مع التغيير تدريجيًا والمحافظة على استقرار العمل.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":37,"mode":"binary","text":"بعد أن أتمكن جيدًا من مجال معين، ثم تتاح لي فرصة لتعلم مجال جديد يختلف عنه ويحتاج مني إلى البدء من مستوى أقل، فإنني غالبًا:","options":[{"text":"أخوض المجال الجديد؛ لأن اكتساب خبرات مختلفة وتوسيع معرفتي أمر مهم بالنسبة لي.","code":"التجديد والتطوير"},{"text":"أفضّل الاستمرار في المجال الذي أعرفه وأتقنه وتطوير خبرتي داخله؛ لأن العمل ضمن مجال مألوف يمنحني ثقة ووضوحًا أكبر.","code":"الاستقرار والأمان"}],"meta":{"indicator":"القيم"}},{"id":38,"mode":"binary","text":"إذا أتقنت مهارة جديدة يحتاجها فريقك في العمل، فكيف تفضل الاستفادة منها؟","options":[{"text":"أحرص على إتقانها وتطبيقها بنفسي في الأعمال المهمة.","code":"القناص"},{"text":"أعمل على نقلها للفريق وأتابع تطبيقهم لها حتى يصبح أداؤهم بالمستوى المطلوب.","code":"الأستاذ"}],"meta":{"indicator":"الدوافع"}},{"id":39,"mode":"binary","text":"قبل اعتماد فكرة جديدة لم تُجرَّب من قبل، وكانت الموارد المتاحة لا تسمح إلا بأحد الخيارين، فأيهما تفضل؟","options":[{"text":"إجراء دراسة تقارن بين نتائج الفكرة المتوقعة ومخاطرها، بالاستناد إلى المعلومات المتاحة.","code":"(A التحليلي)"},{"text":"تطبيق الفكرة على نطاق محدود؛ لاختبارها عمليًا واستكشاف ما قد تتيحه من استخدامات وفرص جديدة.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":40,"mode":"binary","text":"عندما أكون أمام قرار مهم يتعلق بطريقة عيشي أو مستقبلي، ويكون اختياري الشخصي مختلفًا عن التقاليد التي نشأت عليها، فإنني غالبًا:","options":[{"text":"أختار ما أراه مناسبًا لي وفق قناعتي، حتى لو كان مختلفًا بوضوح عن التقاليد السائدة في أسرتي أو مجتمعي.","code":"الاستقلالية"},{"text":"أتمسك بالتقاليد التي نشأت عليها، وأختار ما ينسجم معها حتى لو كان ذلك مخالفًا لما أميل إليه شخصيًا.","code":"الأصالة والنظام"}],"meta":{"indicator":"القيم"}},{"id":41,"mode":"binary","text":"عندما ينخفض حماس الفريق، فإن أكثر ما أحرص عليه غالبًا هو:","options":[{"text":"بث الحماس في الفريق، وتحفيزهم على مواصلة العمل بروح إيجابية.","code":"(I التأثير)"},{"text":"مساعدة الفريق على استعادة هدوئه وتوازنه، والمحافظة على وتيرة عمل مستقرة.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":42,"mode":"binary","text":"عندما أكون في رحلة أو إجازة، وتوجد أعمال غير عاجلة يمكن متابعتها عن بُعد، فإنني غالبًا:","options":[{"text":"أتركها إلى ما بعد الإجازة، وأحرص على أن يكون وقت الرحلة مخصصًا للراحة والاستمتاع دون انشغال مستمر بالعمل.","code":"الاستمتاع بالحياة"},{"text":"أخصص وقتًا محددًا أثناء الإجازة لمتابعة هذه الأعمال؛ حتى أبقى ملتزمًا بمسؤولياتي ولا تتراكم عليّ بعد العودة.","code":"الانضباط والالتزام"}],"meta":{"indicator":"القيم"}},{"id":43,"mode":"binary","text":"إذا طُلب منك جمع معلومات عن موضوع مهم سيُبنى عليها قرار، فكيف تفضل تنفيذ ذلك؟","options":[{"text":"أفضل أن أجمع المعلومات وأتحقق من دقتها بنفسي قبل الاعتماد عليها.","code":"القناص"},{"text":"أوزع محاور البحث على الفريق، ثم أراجع معهم النتائج حتى تكتمل الصورة بدقة.","code":"الأستاذ"}],"meta":{"indicator":"الدوافع"}},{"id":44,"mode":"binary","text":"بعد قراءة قصة، طُلب منك اختيار جانب واحد فقط لمناقشته؛ فأيهما تفضل؟","options":[{"text":"مشاعر الشخصيات، والتغيرات التي طرأت على علاقاتها، وأثر الأحداث فيها.","code":"(C العاطفي)"},{"text":"الأفكار والرموز التي تحملها القصة، والاحتمالات والتصورات الجديدة التي يمكن استخلاصها منها.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":45,"mode":"binary","text":"أثناء تنفيذ مشروع وفق خطة معتمدة، ظهرت فرصة لتنفيذ بعض الأعمال بطريقة مختلفة قد توفر وقتًا وتناسب الظروف الحالية، لكنها ستغيّر جزءًا من تسلسل الخطة المتفق عليها، فإنني غالبًا:","options":[{"text":"أعدّل ترتيب بعض الخطوات وأستفيد من الطريقة الجديدة ما دامت تساعد على إنجاز المشروع بصورة أفضل.","code":"المرونة والتكيف"},{"text":"أستمر وفق تسلسل الخطة المعتمدة كما وُضع من البداية؛ لأن وضوح المنهج وثباته يساعدان على ضبط التنفيذ وتقليل الأخطاء.","code":"الالتزام بالمنهج"}],"meta":{"indicator":"القيم"}},{"id":46,"mode":"binary","text":"عند تنفيذ مشروع جماعي، فإن الدور الأقرب لطريقتي هو:","options":[{"text":"تنسيق التواصل بين أعضاء الفريق وتعزيز التعاون بينهم.","code":"(I التأثير)"},{"text":"متابعة سير التنفيذ والتأكد من أن العمل يسير بصورة منظمة ومتقنة.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":47,"mode":"binary","text":"إذا اتخذت مجموعة أعمل معها قرارًا مهمًا لا يتفق مع الخيار الذي كنت أؤيده، وكانت لدي علاقات أو مكانة تمكنني من محاولة تغيير القرار، فإنني غالبًا:","options":[{"text":"أستخدم قدرتي على التأثير وأحاول إعادة توجيه القرار نحو الخيار الذي أراه أفضل.","code":"التأثير والنفوذ"},{"text":"أتقبل القرار الذي توصلت إليه المجموعة، حتى لو بقي رأيي مختلفًا ولم يكن هو الخيار الذي تم اعتماده.","code":"التسامح وتقبّل الآخرين"}],"meta":{"indicator":"القيم"}},{"id":48,"mode":"binary","text":"إذا كنت تعمل على إنتاج عمل مهم سيُعرض على عدد كبير من الأشخاص، فكيف تفضل تنفيذه؟","options":[{"text":"أفضل تنفيذ العمل بنفسي حتى يخرج بأعلى جودة.","code":"القناص"},{"text":"أقود فريق الإنتاج، وأتابع جودة العمل حتى يخرج بالمستوى المطلوب.","code":"الأستاذ"}],"meta":{"indicator":"الدوافع"}},{"id":49,"mode":"rank","text":"عند المشاركة في تطوير منتج جديد، رتّب المهام التالية بحسب ما تستمتع به أكثر:","options":[{"text":"اختبار أداء المنتج، وتحليل ملاحظات المستخدمين لتقدير مدى نجاحه.","code":"I البحثي"},{"text":"عرض المشروع على المستثمرين، والتفاوض للحصول على التمويل وفرص التسويق.","code":"E الريادي"},{"text":"تصنيع النموذج الأولي، وتجميع مكوناته، ومعالجة العيوب التي تظهر أثناء تجربته.","code":"R الواقعي"},{"text":"رسم شكل المنتج، وتطوير تغليفه بما يمنحه هوية مبتكرة ومميزة.","code":"A الفني"}],"meta":{"indicator":"هولاند"}},{"id":50,"mode":"rank","text":"عند المشاركة في مبادرة لتطوير أحد المرافق العامة، رتّب الأدوار التالية بحسب تفضيلك:","options":[{"text":"تركيب المقاعد وأنظمة الري والإنارة، وتنفيذ أعمال التجهيز في الموقع.","code":"R الواقعي"},{"text":"تنظيم أنشطة لرواد الحديقة، والتفاعل معهم لمساعدتهم على الاستفادة من مرافقها.","code":"S الاجتماعي"},{"text":"رصد استخدام الحديقة ومناطق الازدحام فيها، ومقارنة الحلول الممكنة لتطويرها.","code":"I البحثي"},{"text":"إدارة المشروع، والتنسيق مع الجهات والداعمين لتوفير الموافقات والموارد اللازمة.","code":"E الريادي"}],"meta":{"indicator":"هولاند"}},{"id":51,"mode":"rank","text":"عند المشاركة في تشغيل مزرعة إنتاجية حديثة، رتّب المهام التالية بحسب ما تستمتع به أكثر:","options":[{"text":"زراعة المحاصيل، وتشغيل معدات الري، ومتابعة الأعمال الميدانية.","code":"R الواقعي"},{"text":"إرشاد العاملين، وتعليمهم طرق العناية بالمحاصيل والسلامة أثناء العمل.","code":"S الاجتماعي"},{"text":"فحص التربة والمحاصيل، وتحليل أسباب ضعف الإنتاج، وتجربة الحلول المناسبة.","code":"I البحثي"},{"text":"تسجيل كميات الإنتاج والمصروفات، وتنظيم سجلات المخزون والمبيعات.","code":"C التنظيمي"}],"meta":{"indicator":"هولاند"}},{"id":52,"mode":"rank","text":"عند المشاركة في تشغيل مشروع تجاري صغير، رتّب المهام التالية بحسب ما تستمتع به أكثر:","options":[{"text":"تنظيم الطلبات والمخزون والسجلات وإجراءات التشغيل اليومية.","code":"C التنظيمي"},{"text":"ابتكار الهوية البصرية للمشروع، وتنسيق العبوات والواجهة وطريقة ظهور المنتجات.","code":"A الفني"},{"text":"تجهيز المنتجات وتجميع أجزائها وتغليفها باستخدام الأدوات والمعدات المخصصة.","code":"R الواقعي"},{"text":"جذب العملاء، وإتمام الصفقات، والبحث عن أسواق جديدة لتوسيع المشروع.","code":"E الريادي"}],"meta":{"indicator":"هولاند"}},{"id":53,"mode":"rank","text":"عند إعداد مجلة معرفية، رتّب المهام التالية بحسب ما تستمتع به أكثر:","options":[{"text":"وضع جدول النشر، واستلام المواد في مواعيدها، والتأكد من اكتمالها قبل الإصدار.","code":"C التنظيمي"},{"text":"البحث في المصادر، والتحقق من المعلومات، ومقارنة الآراء المتعلقة بالموضوعات المنشورة.","code":"I البحثي"},{"text":"كتابة مقال أو قصة بأسلوب تعبيري يجذب القارئ ويعكس رؤيتي الخاصة.","code":"A الفني"},{"text":"إجراء مقابلات مع أشخاص مختلفين، والاستماع إلى تجاربهم، ومساعدتهم على عرض أفكارهم بوضوح.","code":"S الاجتماعي"}],"meta":{"indicator":"هولاند"}},{"id":54,"mode":"rank","text":"عند تنظيم برنامج مجتمعي جديد، رتّب الأدوار التالية بحسب تفضيلك:","options":[{"text":"صياغة فكرة البرنامج، وابتكار أنشطته والطريقة التي ستُقدَّم بها.","code":"A الفني"},{"text":"تنظيم التسجيل والمواعيد والميزانية والتجهيزات، ومتابعة تنفيذ الخطة.","code":"C التنظيمي"},{"text":"التواصل مع المشاركين، والاستماع إلى احتياجاتهم، وتقديم الدعم لهم.","code":"S الاجتماعي"},{"text":"بناء الشراكات، وتأمين الدعم، وتوسيع انتشار البرنامج وتأثيره.","code":"E الريادي"}],"meta":{"indicator":"هولاند"}},{"id":55,"mode":"scale","text":"عندما أقرأ قصة أو مقالًا، أستطيع فهم المعاني المقصودة، وملاحظة طريقة صياغة الأفكار، ثم إعادة عرض ما فهمته بوضوح بأسلوبي.","meta":{"indicator":"الذكاءات","dimension":"الذكاء اللغوي"}},{"id":56,"mode":"scale","text":"ذا كُلِّفت بمهمة جديدة لا أعرف جميع خطوات تنفيذها، أحدد الهدف وصلاحياتي، ثم أبدأ العمل وأختار الطريقة المناسبة بنفسي، حتى لو لم أجد من يرشدني في كل خطوة.","meta":{"indicator":"الجدارات","dimension":"المبادرة"}},{"id":57,"mode":"scale","text":"أستطيع التحكم بحركات يدي بدقة عند أداء مهام تتطلب تنسيقًا بين النظر وحركة اليد؛ مثل تركيب قطع صغيرة، أو القص والرسم ضمن حدود محددة.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الحركي"}},{"id":58,"mode":"scale","text":"إذا اكتشفت خطأً مؤثرًا شاركت في حدوثه، أبادر إلى إبلاغ المعنيين وتوضيح دوري في الخطأ والمساعدة في إصلاحه، حتى لو لم يكتشفه أحد وكان الاعتراف به قد يؤثر في تقييمي.","meta":{"indicator":"الجدارات","dimension":"تحمل المسؤولية"}},{"id":59,"mode":"scale","text":"عندما أواجه مهمة جديدة، أستطيع تقدير ما يمكنني إنجازه بقدراتي الحالية، وما يحتاج مني إلى تعلّم إضافي أو طلب المساعدة.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الذاتي"}},{"id":60,"mode":"scale","text":"ا كُلِّفت بتنفيذ ثلاثة مشاريع مهمة في وقت واحد وبموارد محدودة، أستطيع ترتيب أولوياتها وتوزيع الموارد ووضع خطة لإنجازها، حتى لو تعارضت مطالب المسؤولين.","meta":{"indicator":"الجدارات","dimension":"التخطيط والتنظيم"}},{"id":61,"mode":"scale","text":"عندما أستخدم خريطة أو مخططًا لمكان غير مألوف، أستطيع تحديد المواقع والاتجاه الذي يجب أن أسلكه للوصول إلى وجهتي.","meta":{"indicator":"الذكاءات","dimension":"الذكاء البصري"}},{"id":62,"mode":"scale","text":"إذا طلب مني مسؤول اعتماد معاملة لا تستوفي المتطلبات النظامية، أرفض اعتمادها وأوضح الأسباب وأبحث عن حل نظامي، حتى لو تعرضت لضغط مباشر.","meta":{"indicator":"الجدارات","dimension":"النزاهة والموثوقية"}},{"id":63,"mode":"scale","text":"إذا كُلِّفت بشرح قرار تنظيمي جديد لعدة إدارات تعترض عليه، أستطيع توضيح أسبابه وآثاره والإجابة عن اعتراضاتهم حتى يفهم الجميع ما هو مطلوب منهم.","meta":{"indicator":"الجدارات","dimension":"التواصل الفعّال"}},{"id":64,"mode":"scale","text":"عندما أراجع أرقامًا أو بيانات، أستطيع حساب الفروق والنسب بينها، وملاحظة اتجاه الزيادة أو الانخفاض للوصول إلى نتيجة واضحة.","meta":{"indicator":"الذكاءات","dimension":"الذكاء المنطقي"}},{"id":65,"mode":"scale","text":"إذا كُلِّفت باتخاذ قرار عاجل قد يؤثر في عمل عدة إدارات، وكانت المعلومات المتاحة متعارضة، وآراء المسؤولين مختلفة، أستطيع تحديد الخيار الأنسب واتخاذ القرار في الوقت المحدد، حتى لو لم تتضح جميع النتائج وكان عليّ تحمل مسؤولية أي آثار سلبية قد تنتج عنه.","meta":{"indicator":"الجدارات","dimension":"اتخاذ القرار"}},{"id":66,"mode":"scale","text":"إذا اكتشفت فرصة مهمة لتحسين العمل خارج مسؤولياتي، أسعى إلى تطبيقها بالتعاون مع المعنيين، حتى لو واجهت صعوبات ولم يكن نجاحها محسوبًا ضمن إنجازاتي.","meta":{"indicator":"الجدارات","dimension":"المبادرة"}},{"id":67,"mode":"scale","text":"عندما ينشأ خلاف بين شخصين، أفهم سبب تمسّك كل منهما بموقفه، وأساعدهما على اكتشاف نقاط الاتفاق بينهما.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الاجتماعي"}},{"id":68,"mode":"scale","text":"إذا كان أحد أفراد الفريق مستعدًا لتحمل مسؤولية مهمة، أمنحه الصلاحيات المناسبة وأترك له مساحة لاتخاذ قراراته، حتى لو كان أسلوبه مختلفًا عن أسلوبي وكانت نتائجه في البداية أقل من نتائجي.","meta":{"indicator":"الجدارات","dimension":"تطوير الآخرين"}},{"id":69,"mode":"scale","text":"إذا كانت لدي معرفة أو خبرة يحتاجها الفريق لتحقيق نتائج أفضل، أشاركها مع الجميع، حتى لو أدى ذلك إلى تقليل تميزي الشخصي أو منح الآخرين فرصة للنجاح مثلي.","meta":{"indicator":"الجدارات","dimension":"العمل الجماعي"}},{"id":70,"mode":"scale","text":"عندما أتخذ قرارًا وأنا تحت ضغط، ألاحظ ما إذا كان التوتر يؤثر في قراري، فأحاول ألا أتسرع أو أتجنب القرار بسببه.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الذاتي"}},{"id":71,"mode":"scale","text":"إذا تكررت مشكلة تؤثر في سير العمل رغم معالجتها أكثر من مرة، أستطيع تحليل أسبابها الأساسية ووضع حل يمنع تكرارها، حتى لو تطلب ذلك تغيير إجراءات اعتاد عليها الموظفون.","meta":{"indicator":"الجدارات","dimension":"حل المشكلات"}},{"id":72,"mode":"scale","text":"إذا استشرفت وجود متغيرات قد تؤثر في مستقبل العمل، أبادر إلى مراجعة الخطط والاستعداد لها، حتى لو استلزم ذلك تعديل خطط معتمدة أو إعادة تخصيص بعض الموارد، قبل ظهور الحاجة الفعلية إليها، حتى لو لم تظهر نتائجها بعد وكان الآخرون لا يرون حاجة للتحرك.","meta":{"indicator":"الجدارات","dimension":"التفكير الاستراتيجي"}},{"id":73,"mode":"scale","text":"عند حل مسألة أو لغز، لديّ القدرة على تتبّع المعطيات خطوةً خطوة، واكتشاف القاعدة التي تربط بينها للوصول إلى الحل.","meta":{"indicator":"الذكاءات","dimension":"الذكاء المنطقي"}},{"id":74,"mode":"scale","text":"إذا كنت مسؤولًا عن تنفيذ تغيير يؤثر في الآخرين، أتابع مدى تقبلهم له، وأدعمهم لتجاوز الصعوبات التي قد تواجههم أثناء تطبيقه، بدلًا من الاكتفاء بإلزامهم بتطبيقه.","meta":{"indicator":"الجدارات","dimension":"إدارة التغيير"}},{"id":75,"mode":"scale","text":"إذا رفضت الإدارة مشروعًا تطويريًا أعددته، أستطيع إعادة دراسة المشروع وتقديم أدلة وحلول مقنعة للحصول على موافقتها، حتى لو تطلب ذلك تغيير أجزاء أساسية منه.","meta":{"indicator":"الجدارات","dimension":"التأثير والإقناع"}},{"id":76,"mode":"scale","text":"عندما أسمع قراءة أو نشيدًا أو مقطعًا صوتيًا، ألاحظ بسرعة أي تغير أو خلل في النغمة أو الإيقاع.","meta":{"indicator":"الذكاءات","dimension":"الذكاء السمعي"}},{"id":77,"mode":"scale","text":"إذا اختار الفريق طريقة عمل تختلف عن اقتراحي الذي بذلت جهدًا كبيرًا في إعداده، أساند قرار الفريق وأسهم في نجاحه، حتى لو كنت ما زلت أرى أن اقتراحي أفضل.","meta":{"indicator":"الجدارات","dimension":"العمل الجماعي"}},{"id":78,"mode":"scale","text":"إذا كان قرار سيحقق نتائج متميزة لإدارتي لكنه قد يضر بمصلحة المنظمة مستقبلًا، أدعم الخيار الذي يخدم المنظمة ككل، حتى لو أدى ذلك إلى انخفاض نتائج إدارتي التي يُقيَّم أدائي بناءً عليها.","meta":{"indicator":"الجدارات","dimension":"التفكير الاستراتيجي"}},{"id":79,"mode":"scale","text":"ألاحظ غالبًا ما يشعر به الآخرون من نبرة الصوت، وتعبيرات الوجه، ولغة الجسد، حتى عندما لا يتحدثون عن مشاعرهم أو يقولون إنهم بخير.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الاجتماعي"}},{"id":80,"mode":"scale","text":"إذا كنت مسؤولًا عن تطبيق تغيير جديد، وواجه في بدايته اعتراضات أو نتائج أولية غير مشجعة، أواصل تحسينه ومعالجة التحديات قبل التراجع عنه، رغم الضغوط المطالبة بالعودة إلى الطريقة السابقة.","meta":{"indicator":"الجدارات","dimension":"إدارة التغيير"}},{"id":81,"mode":"scale","text":"إذا طُلب مني عرض نتائج تقرير أمام مسؤولين كبار وكانت بعض نتائجه تخالف توقعاتهم، أستطيع عرض النتائج بوضوح والدفاع عنها بالأدلة، حتى لو واجهت اعتراضات قوية.","meta":{"indicator":"الجدارات","dimension":"التواصل الفعّال"}},{"id":82,"mode":"scale","text":"أستطيع اختصار فكرة طويلة في عنوان أو عبارة موجزة تعبّر عن معناها الأساسي.","meta":{"indicator":"الذكاءات","dimension":"الذكاء اللغوي"}},{"id":83,"mode":"scale","text":"عند التعامل مع المشكلات، أتبع منهجية واضحة لتحليلها واختيار الحلول المناسبة، رغم أن الحلول السريعة قد تبدو أسهل في بعض المواقف.","meta":{"indicator":"الجدارات","dimension":"حل المشكلات"}},{"id":84,"mode":"scale","text":"إذا تبين لي أن قرارًا اتخذته لم يعد الأنسب بعد ظهور معطيات جديدة، أبادر إلى تعديله أو التراجع عنه، حتى لو كان ذلك قد يؤثر في صورتي أمام الآخرين.","meta":{"indicator":"الجدارات","dimension":"اتخاذ القرار"}},{"id":85,"mode":"scale","text":"عندما يحتوي المجلس على قطع أثاث متعددة بأحجام مختلفة، إضافة إلى الطاولات واللوحات والإضاءة، أستطيع تصوّر توزيعها بطريقة متناسقة تحقق أفضل استفادة من المساحة قبل البدء في ترتيبها.","meta":{"indicator":"الذكاءات","dimension":"الذكاء البصري"}},{"id":86,"mode":"scale","text":"إذا تأخر مشروع مهم عن موعده، أستطيع إعادة جدولة الأعمال وتوزيع المسؤوليات لمعالجة التأخير، حتى لو تطلب ذلك تعديل اتفاقات سابقة مع جهات أخرى.","meta":{"indicator":"الجدارات","dimension":"التخطيط والتنظيم"}},{"id":87,"mode":"scale","text":"إذا تعثر مشروع تحت مسؤوليتي، أراجع قراراتي وأعترف بما قد أكون تسببت فيه من قصور، وأتابع معالجة المشكلة، بدلًا من الاكتفاء بالاعتذار عن المشروع أو تسليمه لشخص آخر.","meta":{"indicator":"الجدارات","dimension":"تحمل المسؤولية"}},{"id":88,"mode":"scale","text":"بعد الاستماع إلى شرح أو مناقشة، أستطيع تذكّر الأفكار الرئيسة وتسلسلها دون الحاجة إلى قراءتها.","meta":{"indicator":"الذكاءات","dimension":"الذكاء السمعي"}},{"id":89,"mode":"scale","text":"إذا لاحظت ضعفًا متكررًا في أداء أحد أفراد الفريق، أناقشه بأمثلة واضحة وأضع معه خطوات للتحسين وأتابع تقدمه، حتى لو استغرق ذلك وقتًا وجهدًا إضافيين.","meta":{"indicator":"الجدارات","dimension":"تطوير الآخرين"}},{"id":90,"mode":"scale","text":"إذا كُلِّفت بقيادة مشروع لا يؤيده بعض أعضاء الفريق، أستطيع إقناعهم بأهميته وكسب مشاركتهم الفعلية، دون الاكتفاء بإلزامهم بتنفيذ التعليمات.","meta":{"indicator":"الجدارات","dimension":"التأثير والإقناع"}},{"id":91,"mode":"scale","text":"أستطيع استخدام الأدوات لتنفيذ عمل يدوي وفق فكرة أو مخطط؛ مثل صنع مجسّم، أو تجميع أجزاء جهاز، أو إصلاح عطل بسيط.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الحركي"}},{"id":92,"mode":"scale","text":"إذا طُلب مني تقييم شخص أعرفه أو تربطني به علاقة جيدة، ألتزم بمعايير التقييم نفسها التي أطبقها على الآخرين، وأحرص على أن يكون تقييمي عادلًا وموضوعيًا، رغم أن ذلك قد لا يرضيه وقد تتأثر علاقتي به..","meta":{"indicator":"الجدارات","dimension":"النزاهة والموثوقية"}}],"student":[{"id":1,"mode":"binary","text":"عندما يعطيك المعلم مشروعًا جديدًا ولم يحدد لك طريقة تنفيذه، ما الذي تبدأ به غالبًا؟","options":[{"text":"أؤجل البدء حتى أفهم الموضوع جيدًا، وأعرف أسبابه والعلاقات بين معلوماته.","code":"A التحليلي"},{"text":"أبدأ بتنظيم العمل إلى خطوات واضحة، وأحدد ما سأفعله أولًا ثم ما يليه.","code":"B التنفيذي"}],"meta":{"indicator":"هيرمان"}},{"id":2,"mode":"binary","text":"عندما نبدأ مشروعًا جماعيًا في المدرسة، فإنني أميل إلى:","options":[{"text":"المبادرة بتحديد ما نحتاج إلى إنجازه وتوجيه المجموعة للبدء سريعًا.","code":"D الهيمنة"},{"text":"التحدث مع زملائي ورفع حماسهم للمشاركة في المشروع.","code":"I التأثير"}],"meta":{"indicator":"ديسك"}},{"id":3,"mode":"binary","text":"طُلب من مجموعتك تنفيذ مشروع مدرسي خلال وقت محدود، فهل:","options":[{"text":"أبدأ بنفسي في الأعمال المهمة حتى ينطلق المشروع بسرعة.","code":"(المقاتل المنفرد)"},{"text":"أجمع زملائي، وأوزع المهام، وأشجعهم على العمل معًا.","code":"(قائد التشجيع)"}],"meta":{"indicator":"الدوافع"}},{"id":4,"mode":"binary","text":"بعد أسبوع دراسي مزدحم، وفي عطلة نهاية الأسبوع، إذا كان لدي وقت فراغ فأنا أقرب إلى:","options":[{"text":"استخدام الوقت في نشاط أحبه أو الاستمتاع به قبل العودة إلى الالتزامات.","code":"الاستمتاع بالحياة"},{"text":"استغلال الوقت في إنهاء ما لدي من واجبات أو ترتيب أعمالي القادمة.","code":"الانضباط والالتزام"}],"meta":{"indicator":"القيم"}},{"id":5,"mode":"binary","text":"إذا أخبرك صديق بأنه تشاجر مع شخص آخر، ما أول شيء يلفت اهتمامك؟","options":[{"text":"معرفة ما حدث بالضبط، وما الأسباب التي أدت إلى الخلاف.","code":"A التحليلي"},{"text":"معرفة شعور صديقك، وكيف أثّر الخلاف فيه وفي علاقته بالشخص الآخر.","code":"C العاطفي"}],"meta":{"indicator":"هيرمان"}},{"id":6,"mode":"binary","text":"إذا واجهت مجموعتي صعوبة مفاجئة أثناء تنفيذ نشاط، فإنني أميل إلى:","options":[{"text":"التعامل مباشرة مع المشكلة واقتراح ما يجب فعله لمواصلة العمل.","code":"D الهيمنة"},{"text":"المحافظة على هدوء المجموعة ومساعدتها على الاستمرار دون ارتباك.","code":"S الثبات"}],"meta":{"indicator":"ديسك"}},{"id":7,"mode":"binary","text":"إذا أتيحت لي فرصة المشاركة في نشاط جديد لم أجربه من قبل، فأنا أقرب إلى:","options":[{"text":"تجربته لأنني أحب اكتشاف أشياء وطرق جديدة.","code":"التجديد والتطوير"},{"text":"اختيار نشاط أعرفه وأشعر أنني أستطيع التعامل معه بثقة.","code":"الاستقرار والأمان"}],"meta":{"indicator":"القيم"}},{"id":8,"mode":"binary","text":"عندما تبدأ دراسة موضوع لم تعرفه من قبل، ماذا تفعل غالبًا؟","options":[{"text":"أركز على فهم المعلومات ومعرفة كيف ترتبط ببعضها.","code":"A التحليلي"},{"text":"أربط الموضوع بأفكار أخرى، وأفكر في أشياء جديدة يمكن أن تنتج عنه.","code":"D الإبداعي"}],"meta":{"indicator":"هيرمان"}},{"id":9,"mode":"binary","text":"عندما تكون أمامي مهمة دراسية ووقتها محدود، فإنني أميل إلى:","options":[{"text":"البدء سريعًا والتركيز على الوصول إلى النتيجة المطلوبة.","code":"D الهيمنة"},{"text":"التأكد من فهم المطلوب وترتيب خطوات العمل قبل التنفيذ.","code":"C الدقة"}],"meta":{"indicator":"ديسك"}},{"id":10,"mode":"binary","text":"طُلب من مجموعتك إعداد عرض مهم أمام الطلاب، فماذا تفضل؟","options":[{"text":"أتولى الأجزاء التي تحتاج إلى أعلى مستوى من الدقة حتى أضمن جودتها بنفسي.","code":"(القناص)"},{"text":"أوزع الأجزاء على زملائي، وأساعدهم حتى يخرج العرض بالمستوى المطلوب.","code":"(الأستاذ)"}],"meta":{"indicator":"الدوافع"}},{"id":11,"mode":"binary","text":"أثناء تنفيذ مشروع، اكتشفت أن الخطة الموضوعة أصبحت صعبة التطبيق، فأنا أقرب إلى:","options":[{"text":"تعديل الخطة بما يناسب الوضع الجديد حتى نستمر في العمل.","code":"المرونة والتكيف"},{"text":"محاولة الالتزام بالخطة الأصلية والمحافظة على خطواتها قدر الإمكان.","code":"الالتزام بالمنهج"}],"meta":{"indicator":"القيم"}},{"id":12,"mode":"binary","text":"عندما تستخدم برنامجًا أو تطبيقًا جديدًا لأول مرة، ماذا تفعل غالبًا؟","options":[{"text":"أتعلم طريقة استخدامه خطوة بخطوة وألتزم بالخيارات الواضحة فيه.","code":"B التنفيذي"},{"text":"أجرب الأزرار والخصائص بنفسي لأكتشف طرقًا مختلفة لاستخدامه.","code":"D الإبداعي"}],"meta":{"indicator":"هيرمان"}},{"id":13,"mode":"binary","text":"عندما أنضم إلى مجموعة من الطلاب لا أعرفهم جيدًا، فإنني غالبًا:","options":[{"text":"أبدأ الحديث معهم وأحاول تكوين جو ممتع ومريح بسرعة.","code":"I التأثير"},{"text":"أتعرف عليهم بهدوء وأترك العلاقة تتطور مع الوقت.","code":"S الثبات"}],"meta":{"indicator":"ديسك"}},{"id":14,"mode":"binary","text":"أثناء مشروع جماعي مهم، مرّ أحد أعضاء الفريق بظرف شخصي وأصبح أقل قدرة على الإنجاز، فأنا أقرب إلى:","options":[{"text":"البحث عن طريقة تحافظ على مستوى المشروع والنتيجة المطلوبة.","code":"الإنجاز والإتقان"},{"text":"تخفيف بعض المهام عنه ومراعاة ظروفه حتى لو تأثر مستوى الإنجاز قليلًا.","code":"الرعاية والرحمة"}],"meta":{"indicator":"القيم"}},{"id":15,"mode":"binary","text":"عندما تسمع قصة أو تجربة مر بها شخص آخر،ما الذي يبقى في ذهنك أكثر؟","options":[{"text":"مشاعر الشخص، وما مرّ به، وكيف أثرت التجربة في علاقاته بالآخرين.","code":"C العاطفي"},{"text":"الأفكار والتصورات الجديدة التي تثيرها القصة في ذهنك.","code":"D الإبداعي"}],"meta":{"indicator":"هيرمان"}},{"id":16,"mode":"binary","text":"عندما أقدم عرضًا أمام الصف، فإنني أهتم أكثر بأن:","options":[{"text":"يكون العرض مشوقًا ويجذب انتباه الطلاب ويشجعهم على التفاعل.","code":"I التأثير"},{"text":"تكون المعلومات مرتبة وواضحة وصحيحة.","code":"C الدقة"}],"meta":{"indicator":"ديسك"}},{"id":17,"mode":"binary","text":"تستعد مع مجموعة من زملائك لاختبار مهم، فأيهما أقرب لطريقتك؟","options":[{"text":"أركز على خطة مراجعتي الخاصة وأعتمد على جهدي للوصول إلى أفضل نتيجة.","code":"(المقاتل المنفرد)"},{"text":"أنظم المراجعة مع زملائي، وأشجعهم على تبادل الشرح حتى يستفيد الجميع.","code":"(قائد التشجيع)"}],"meta":{"indicator":"الدوافع"}},{"id":18,"mode":"binary","text":"في نقاش جماعي حول فكرة مهمة، فأنا أقرب إلى:","options":[{"text":"محاولة إقناع المجموعة بالفكرة التي أراها الأفضل وجمع التأييد لها.","code":"التأثير والنفوذ"},{"text":"إعطاء مساحة كبيرة للآراء المختلفة حتى لو لم تكن قريبة من رأيي.","code":"التسامح وتقبّل الآخرين"}],"meta":{"indicator":"القيم"}},{"id":19,"mode":"binary","text":"إذا أخطأت في حل مسألة عدة مرات، ماذا تفعل غالبًا؟","options":[{"text":"أبحث عن السبب الذي جعل إجابتي خاطئة، وأحاول فهم أين كان الخطأ في تفكيري.","code":"A التحليلي"},{"text":"أرجع إلى خطوات الحل الصحيحة وأطبقها بالترتيب حتى أصل إلى الإجابة.","code":"B التنفيذي"}],"meta":{"indicator":"هيرمان"}},{"id":20,"mode":"binary","text":"إذا طُلب منا تنفيذ مشروع دراسي بطريقة جديدة لم نعتد عليها، فإنني أميل إلى:","options":[{"text":"تفضيل طريقة مألوفة وواضحة أشعر معها بالراحة والاستقرار أثناء العمل.","code":"S الثبات"},{"text":"التركيز على فهم خطوات الطريقة الجديدة بالتفصيل، والتأكد من تنفيذها بالطريقة الصحيحة.","code":"C الدقة"}],"meta":{"indicator":"ديسك"}},{"id":21,"mode":"binary","text":"عند المشاركة في مسابقة أو نشاط مدرسي، فأنا أقرب إلى:","options":[{"text":"البحث عن دور يتيح لي التميز وإظهار قدراتي والوصول إلى نتيجة عالية.","code":"الطموح والمكانة"},{"text":"القيام بالدور الذي يحتاجه الفريق حتى لو كان أقل ظهورًا أمام الآخرين.","code":"التواضع والخدمة"}],"meta":{"indicator":"القيم"}},{"id":22,"mode":"binary","text":"عندما تفكر في مشروع أو نشاط جديد، ما الذي يشد اهتمامك أكثر؟","options":[{"text":"ما الذي يمكن أن ينجح الآن بناءً على المعلومات المتوفرة والنتائج المتوقعة.","code":"A التحليلي"},{"text":"كيف يمكن أن يتطور المشروع في المستقبل، وما الفرص الجديدة التي قد تظهر بسببه.","code":"D الإبداعي"}],"meta":{"indicator":"هيرمان"}},{"id":23,"mode":"binary","text":"عندما تختلف آراء مجموعتي حول الطريقة الأفضل لإنجاز المهمة، فإنني أميل إلى:","options":[{"text":"توجيه النقاش نحو اختيار قرار واضح حتى نتمكن من مواصلة العمل.","code":"D الهيمنة"},{"text":"مناقشة زملائي وشرح الفكرة التي أراها مناسبة بطريقة تشجعهم على الاقتناع بها ودعمها.","code":"I التأثير"}],"meta":{"indicator":"ديسك"}},{"id":24,"mode":"binary","text":"تعلمت مهارة جديدة يحتاجها زملاؤك في مشروع دراسي، فهل:","options":[{"text":"أستخدمها بنفسي في الأجزاء المهمة التي تتطلب إتقانًا عاليًا.","code":"(القناص)"},{"text":"أشرحها لزملائي وأتابع تطبيقهم حتى يتمكنوا منها بأنفسهم.","code":"(الأستاذ)"}],"meta":{"indicator":"الدوافع"}},{"id":25,"mode":"binary","text":"في الإجازة، إذا أتيحت لي فرصتان متقاربتان في المتعة، فأنا أقرب إلى:","options":[{"text":"اختيار الفرصة التي تعود عليّ بمكافأة أو فائدة شخصية أكبر.","code":"المادية"},{"text":"اختيار الفرصة التي أستطيع من خلالها تقديم فائدة أكبر للآخرين، حتى لو كانت فائدتي الشخصية منها أقل.","code":"العطاء"}],"meta":{"indicator":"القيم"}},{"id":26,"mode":"binary","text":"إذا انضم طالب جديد إلى مجموعتك أثناء تنفيذ مهمة، ماذا تفعل أولًا؟","options":[{"text":"أوضح له دوره، وما المطلوب منه، والخطوات التي يجب أن يتبعها.","code":"B التنفيذي"},{"text":"أتعرف إليه وأساعده على الشعور بالراحة مع أفراد المجموعة.","code":"C العاطفي"}],"meta":{"indicator":"هيرمان"}},{"id":27,"mode":"binary","text":"عندما يتأخر بعض زملائي في إنجاز الجزء المطلوب منهم، فإنني أميل إلى:","options":[{"text":"تنبيههم إلى التأخير وحثهم على الإسراع حتى ننجز المهمة في الوقت المطلوب.","code":"D الهيمنة"},{"text":"معرفة سبب التأخير ومساعدتهم بهدوء حتى يتمكنوا من إكمال الجزء المطلوب منهم.","code":"S الثبات"}],"meta":{"indicator":"ديسك"}},{"id":28,"mode":"binary","text":"إذا أعطاني المعلم طريقة محددة لتنفيذ مهمة، ثم وجدت طريقة أخرى أسهل، فأنا أقرب إلى:","options":[{"text":"استخدام الطريقة الأخرى إذا كانت تحقق المطلوب بشكل جيد.","code":"المرونة والتكيف"},{"text":"تنفيذ المهمة بالطريقة المحددة حتى أتأكد أنني التزمت بالمطلوب.","code":"الالتزام بالمنهج"}],"meta":{"indicator":"القيم"}},{"id":29,"mode":"binary","text":"حدثت مشكلة أثناء نشاط جماعي، فماذا تفعل غالبًا؟","options":[{"text":"أتدخل مباشرة وأحاول معالجة المشكلة حتى يعود النشاط إلى مساره.","code":"(المقاتل المنفرد)"},{"text":"أجمع المشاركين وأحفزهم للوصول إلى حل وتنفيذه معًا.","code":"(قائد التشجيع)"}],"meta":{"indicator":"الدوافع"}},{"id":30,"mode":"binary","text":"قبل اختبار مهم، كان لدي وقت محدود للمراجعة، وطلب مني زميل متعثر أن أساعده في فهم جزء من المادة، فأنا أقرب إلى:","options":[{"text":"إعطاء الأولوية لمراجعتي واستعدادي للاختبار؛ لأن وقتي محدود ونتيجتي مسؤولية أتحملها بنفسي.","code":"الإنجاز والإتقان"},{"text":"تخصيص جزء من وقت المراجعة لمساعدته، حتى لو قل الوقت المتبقي لاستعدادي الشخصي.","code":"الرعاية والرحمة"}],"meta":{"indicator":"القيم"}},{"id":31,"mode":"binary","text":"عندما تخطط مجموعتك لمشروع يستمر عدة أشهر، ما الذي تهتم به أكثر؟","options":[{"text":"تحديد الخطوات والمواعيد والمسؤوليات حتى يسير العمل بانتظام.","code":"B التنفيذي"},{"text":"تصور الاتجاه الذي يمكن أن يصل إليه المشروع مستقبلًا، وما الفرص الجديدة التي يمكن تطويرها أثناء الطريق.","code":"D الإبداعي"}],"meta":{"indicator":"هيرمان"}},{"id":32,"mode":"binary","text":"إذا كان لدي واجب دراسي مهم، فإنني أميل إلى:","options":[{"text":"التركيز على إنجاز الواجب والوصول إلى النتيجة المطلوبة، وتغيير طريقتي إذا وجدت طريقة أسرع لإنجازه.","code":"D الهيمنة"},{"text":"اتباع خطوات واضحة في إنجازه، ثم مراجعة ما كتبت للتأكد من صحته وعدم وجود أخطاء.","code":"C الدقة"}],"meta":{"indicator":"ديسك"}},{"id":33,"mode":"binary","text":"إذا نجح مشروع شاركت فيه نجاحًا كبيرًا، فأنا أقرب إلى:","options":[{"text":"الاهتمام بأن يعرف الآخرون مساهمتي وما قدمته لتحقيق النجاح.","code":"الطموح والمكانة"},{"text":"الاكتفاء بنجاح المشروع حتى لو لم يعرف معظم الناس حجم دوري فيه.","code":"التواضع والخدمة"}],"meta":{"indicator":"القيم"}},{"id":34,"mode":"binary","text":"لاحظت أن مجموعتك تكرر الخطأ نفسه في أحد الأعمال، فهل:","options":[{"text":"أراجع العمل بنفسي وأصحح الأخطاء حتى يصبح دقيقًا.","code":"(القناص)"},{"text":"أوضح لزملائي سبب الأخطاء وأساعدهم على تجنبها في المرات القادمة.","code":"(الأستاذ)"}],"meta":{"indicator":"الدوافع"}},{"id":35,"mode":"binary","text":"إذا كان لدي شيء جيد لم أعد أستخدمه كثيرًا وكان أحد أصدقائي يحتاج إليه، فأنا أقرب إلى:","options":[{"text":"الاحتفاظ به لأنني قد أحتاج إليه مرة أخرى في المستقبل.","code":"المادية"},{"text":"إعطائه له إذا كنت أرى أنه سينتفع به أكثر مني الآن.","code":"العطاء"}],"meta":{"indicator":"القيم"}},{"id":36,"mode":"binary","text":"إذا كانت مجموعتك ستقدم عرضًا أمام الطلاب، ما الجانب الذي تهتم به أكثر؟","options":[{"text":"أن يشعر الحضور بأن العرض قريب منهم، وأن يتفاعلوا معه ويشاركوا أثناءه.","code":"C العاطفي"},{"text":"أن تكون طريقة العرض مبتكرة ومختلفة، وتقدم الفكرة بأسلوب غير معتاد.","code":"D الإبداعي"}],"meta":{"indicator":"هيرمان"}},{"id":37,"mode":"binary","text":"في الأنشطة والرحلات المدرسية، فإنني غالبًا:","options":[{"text":"أستمتع بالتحدث مع عدد كبير من الطلاب والمشاركة في الأجواء والحماس.","code":"I التأثير"},{"text":"أفضل قضاء الوقت مع الطلاب الذين أعرفهم جيدًا وأشعر معهم براحة أكبر.","code":"S الثبات"}],"meta":{"indicator":"ديسك"}},{"id":38,"mode":"binary","text":"عندما أختار كيف أتصرف في موقف لا توجد فيه تعليمات واضحة، فأنا أقرب إلى:","options":[{"text":"الاعتماد على قناعتي الشخصية واتخاذ القرار الذي أراه مناسبًا.","code":"الاستقلالية"},{"text":"الرجوع إلى ما اعتدنا عليه من قواعد وعادات قبل اتخاذ القرار.","code":"الأصالة والنظام"}],"meta":{"indicator":"القيم"}},{"id":39,"mode":"binary","text":"شاركت في منافسة جماعية، فأيهما يمنحك حماسًا أكبر؟","options":[{"text":"أن يكون لي دور أعتمد فيه على أدائي الشخصي لتحقيق نتيجة قوية.","code":"(المقاتل المنفرد)"},{"text":"أن أحفز المجموعة وأساعدها على العمل بروح واحدة لتحقيق الفوز.","code":"(قائد التشجيع)"}],"meta":{"indicator":"الدوافع"}},{"id":40,"mode":"binary","text":"بعد الانتهاء من اختبار أو مشروع بذلت فيه جهدًا كبيرًا، فأنا أقرب إلى:","options":[{"text":"تخصيص وقت للاحتفال أو القيام بشيء أستمتع به قبل التفكير في المهمة التالية.","code":"الاستمتاع بالحياة"},{"text":"البدء في ترتيب المهمة أو الهدف التالي إذا كان لدي شيء مهم ينتظرني.","code":"الانضباط والالتزام"}],"meta":{"indicator":"القيم"}},{"id":41,"mode":"binary","text":"إذا قرأت خبرًا أثار نقاشًا بين الطلاب، ما الذي يهمك أكثر؟","options":[{"text":"التحقق من صحة المعلومات ومقارنة الأدلة قبل تكوين رأيي.","code":"A التحليلي"},{"text":"معرفة كيف تلقّى الناس الخبر، وما المشاعر التي أثارها لديهم.","code":"C العاطفي"}],"meta":{"indicator":"هيرمان"}},{"id":42,"mode":"binary","text":"عندما نناقش فكرة لمشروع أو نشاط جديد، فإنني أميل إلى:","options":[{"text":"عرض الفكرة بطريقة مشوقة تشجع زملائي على الحماس لها والمشاركة فيها.","code":"I التأثير"},{"text":"التفكير في تفاصيل الفكرة ومتطلباتها، والتأكد من إمكانية تنفيذها بشكل صحيح.","code":"C الدقة"}],"meta":{"indicator":"ديسك"}},{"id":43,"mode":"binary","text":"إذا ظهرت أداة أو وسيلة جديدة يمكن أن تساعدني في الدراسة أو إنجاز المهام، فأنا أقرب إلى:","options":[{"text":"تعلم استخدامها وتجربتها؛ للاستفادة مما يمكن أن تضيفه إلى طريقتي الحالية.","code":"التجديد والتطوير"},{"text":"الاستمرار باستخدام الأدوات والطرق التي أعرفها وأثق بنتائجها ما دامت تؤدي المطلوب.","code":"الاستقرار والأمان"}],"meta":{"indicator":"القيم"}},{"id":44,"mode":"binary","text":"عندما تعمل مجموعتك على مهمة في غاية الأهمية، فأيهما يرضيك أكثر؟","options":[{"text":"أن أُنجز جزءًا صعبًا بدقة عالية حتى يخرج العمل بالمستوى الذي أريده.","code":"(القناص)"},{"text":"أن أساعد زملائي على تحسين أدائهم حتى يصبحوا قادرين على إنجاز العمل بشكل أفضل.","code":"(الأستاذ)"}],"meta":{"indicator":"الدوافع"}},{"id":45,"mode":"binary","text":"عندما يكون لدي اقتراح أراه مهمًا للمدرسة أو الفريق، فأنا أقرب إلى:","options":[{"text":"التواصل مع الأشخاص المؤثرين ومحاولة الحصول على دعمهم لتنفيذه.","code":"التأثير والنفوذ"},{"text":"عرضه والاستماع إلى الآراء المختلفة حوله، حتى لو أدى ذلك إلى تعديله بصورة كبيرة.","code":"التسامح وتقبّل الآخرين"}],"meta":{"indicator":"القيم"}},{"id":46,"mode":"binary","text":"إذا شاركت في تنظيم فعالية مدرسية، ما الذي تفكر فيه أكثر؟","options":[{"text":"ترتيب البرنامج والتجهيزات والمواعيد، والتأكد من سير الفعالية وفق الخطة.","code":"B التنفيذي"},{"text":"أن يشعر المشاركون بالراحة والحماس، وأن يتفاعلوا مع الفعالية ويستمتعوا بها.","code":"C العاطفي"}],"meta":{"indicator":"هيرمان"}},{"id":47,"mode":"binary","text":"عندما أعمل على واجب أو مشروع يحتاج إلى عدة أيام، فإنني أميل إلى:","options":[{"text":"الاستمرار في العمل عليه بهدوء وبشكل ثابت حتى أنتهي منه، دون أن أهتم كثيرًا بتقسيمه إلى أجزاء محددة.","code":"S الثبات"},{"text":"تقسيمه إلى أجزاء واضحة، ومراجعة كل جزء للتأكد من اكتماله بالشكل المطلوب.","code":"C الدقة"}],"meta":{"indicator":"ديسك"}},{"id":48,"mode":"binary","text":"عندما يكون لدي رأي مختلف عن الرأي المعتاد في موضوع مهم، فأنا أقرب إلى:","options":[{"text":"التعبير عن الرأي الذي أقتنع به، حتى لو كان مختلفًا عما اعتاده من حولي.","code":"الاستقلالية"},{"text":"مراعاة القيم والقواعد التي تربيت عليها قبل تبني رأي مختلف عنها.","code":"الأصالة والنظام"}],"meta":{"indicator":"القيم"}},{"id":49,"mode":"rank","text":"إذا قررت صنع هدية أو قطعة بسيطة لشخص قريب منك، رتّب ما تستمتع به أكثر:","options":[{"text":"ابتكار شكل مميز للهدية وإضافة لمسات خاصة عليها.","code":"A – الفني"},{"text":"ترتيب خطوات العمل والمواد المطلوبة قبل البدء.","code":"C – التنظيمي"},{"text":"استخدام الأدوات وصنع القطعة بيدي.","code":"R – الواقعي"},{"text":"البحث عن أفضل المواد والطرق المناسبة لصنعها.","code":"I – البحثي"}],"meta":{"indicator":"هولاند"}},{"id":50,"mode":"rank","text":"عندما تشارك مع أفراد الأسرة في اختيار جهاز إلكتروني جديد للمنزل، رتّب ما تفضله أكثر:","options":[{"text":"البحث عن كيفية عمل الجهاز، وفهم الفروق التقنية بين الخيارات قبل الاختيار.","code":"I – البحثي"},{"text":"مناقشة الخيارات مع الآخرين ومحاولة التأثير في القرار نحو الخيار الذي أراه أفضل.","code":"E – الريادي"},{"text":"تجربة الأجهزة بنفسي والتعامل معها عمليًا قبل اتخاذ القرار.","code":"R – الواقعي"},{"text":"ترتيب الأسعار والمواصفات والخيارات في قائمة واضحة تساعدني على المتابعة والاختيار.","code":"C – التنظيمي"}],"meta":{"indicator":"هولاند"}},{"id":51,"mode":"rank","text":"عند المشاركة في نشاط تطوعي لخدمة الحي، رتّب الأدوار التالية بحسب ما تستمتع به أكثر:","options":[{"text":"تنفيذ الأعمال الميدانية والتجهيزات المطلوبة.","code":"R – الواقعي"},{"text":"التعامل مع المستفيدين ومساعدتهم وتقديم الدعم لهم.","code":"S – الاجتماعي"},{"text":"ابتكار أفكار أو وسائل جديدة تجعل النشاط أكثر جاذبية.","code":"A – الفني"},{"text":"قيادة المجموعة وتوزيع الأدوار وتشجيع الآخرين على المشاركة.","code":"E – الريادي"}],"meta":{"indicator":"هولاند"}},{"id":52,"mode":"rank","text":"إذا أردت تقديم فكرة أو موضوع يهمك لمجموعة من الناس، رتّب ما تستمتع به أكثر:","options":[{"text":"البحث في الموضوع وجمع المعلومات والتأكد من دقتها.","code":"I – البحثي"},{"text":"التحدث أمام الآخرين وإقناعهم بالفكرة.","code":"E – الريادي"},{"text":"ابتكار طريقة مميزة ومختلفة لعرض الفكرة.","code":"A – الفني"},{"text":"تبسيط الفكرة للآخرين ومساعدتهم على فهمها.","code":"S – الاجتماعي"}],"meta":{"indicator":"هولاند"}},{"id":53,"mode":"rank","text":"إذا أنشأت حسابًا أو قناة تهتم بموضوع تحبه، رتّب المهام التالية:","options":[{"text":"كتابة المحتوى أو تصويره وتصميمه بأسلوبي الخاص.","code":"A – الفني"},{"text":"ترتيب الموضوعات ومواعيد النشر ومتابعة ما تم نشره.","code":"C – التنظيمي"},{"text":"البحث عن المعلومات والتحقق منها قبل استخدامها.","code":"I – البحثي"},{"text":"التواصل مع المتابعين والاستماع إلى آرائهم والإجابة عنهم.","code":"S – الاجتماعي"}],"meta":{"indicator":"هولاند"}},{"id":54,"mode":"rank","text":"عند التخطيط لرحلة مع مجموعة من الأصدقاء أو الأسرة، رتّب ما تفضله أكثر:","options":[{"text":"تجهيز الأدوات والاحتياجات والمشاركة في الأعمال العملية أثناء الرحلة.","code":"R – الواقعي"},{"text":"الاهتمام بأفراد المجموعة ومساعدتهم والتأكد من راحتهم.","code":"S – الاجتماعي"},{"text":"قيادة المجموعة واتخاذ القرارات عند اختلاف الآراء.","code":"E – الريادي"},{"text":"إعداد الجدول والمواعيد وقائمة الاحتياجات وتنظيم تفاصيل الرحلة.","code":"C – التنظيمي"}],"meta":{"indicator":"هولاند"}},{"id":55,"mode":"scale","text":"أستمتع بقراءة القصص والمقالات، وأنتبه إلى معاني الكلمات وطريقة صياغة الأفكار، ثم أعبّر عما فهمته بأسلوبي.","meta":{"indicator":"الذكاءات","dimension":"اللغوي"}},{"id":56,"mode":"scale","text":"عندما يكون لدي أكثر من اختبار أو واجب في الفترة نفسها، أحدد ما يحتاج إلى وقت أكبر وأرتب أولوياتي قبل البدء.","meta":{"indicator":"الجدارات","dimension":"2. التخطيط وإدارة الوقت"}},{"id":57,"mode":"scale","text":"عندما أراجع أرقامًا أو بيانات متعددة، أستطيع حساب الفروق والنسب بينها، وملاحظة الأنماط واتجاهات الزيادة أو الانخفاض؛ للوصول إلى نتيجة واضحة.","meta":{"indicator":"الذكاءات","dimension":"المنطقي"}},{"id":58,"mode":"scale","text":"عندما أبدأ المذاكرة أو إنجاز واجب، أستطيع الاستمرار فيه رغم وجود الهاتف أو الألعاب أو أشياء أخرى أفضل القيام بها في ذلك الوقت.","meta":{"indicator":"الجدارات","dimension":"1. إدارة الذات والانضباط"}},{"id":59,"mode":"scale","text":"أفهم الخرائط والمخططات بسهولة، وأستطيع استخدامها لتحديد المواقع والاتجاهات أو الوصول إلى مكان لم أزره من قبل.","meta":{"indicator":"الذكاءات","dimension":"البصري"}},{"id":60,"mode":"scale","text":"إذا أخفقت في تنفيذ جزء من مشروع جماعي كنت مسؤولًا عنه، أتحمل مسؤوليتي وأعمل على معالجة التقصير بدلًا من الاكتفاء بتقديم المبررات.","meta":{"indicator":"الجدارات","dimension":"3. تحمل المسؤولية"}},{"id":61,"mode":"scale","text":"أعرف المهام التي أتميز فيها والمهام التي تحتاج مني إلى تطوير أو مساعدة، وأراعي ذلك عند تحمّل المسؤوليات.","meta":{"indicator":"الذكاءات","dimension":"الذاتي"}},{"id":62,"mode":"scale","text":"عندما أشرح فكرة لزملائي، أغيّر طريقة الشرح أو أعطي مثالًا آخر إذا لاحظت أنهم لم يفهموا ما أقصده.","meta":{"indicator":"الجدارات","dimension":"6. التواصل الفعّال"}},{"id":63,"mode":"scale","text":"أميل إلى المسائل والألعاب التي تتطلب اكتشاف قاعدة خفية أو اتباع سلسلة من الاستنتاجات للوصول إلى الحل.","meta":{"indicator":"الذكاءات","dimension":"المنطقي"}},{"id":64,"mode":"scale","text":"عندما أعمل ضمن مجموعة، أنجز الجزء المسؤول عنه وأساعد في المهام المشتركة إذا احتاج الفريق إلى ذلك.","meta":{"indicator":"الجدارات","dimension":"7. التعاون والعمل الجماعي"}},{"id":65,"mode":"scale","text":"أستطيع التعبير عن الأفكار والمشاعر من خلال الأداء الجسدي؛ مثل التمثيل، أو الإلقاء المصحوب بالإشارات، أو تقليد حركة لشرح موقف.","meta":{"indicator":"الذكاءات","dimension":"الحركي"}},{"id":66,"mode":"scale","text":"إذا تغيرت خطة كنت مستعدًا لها، أستطيع إعادة ترتيب ما سأفعله والتعامل مع الوضع الجديد بدلًا من أن يعطلني التغيير لفترة طويلة.","meta":{"indicator":"الجدارات","dimension":"8. المرونة والتكيف"}},{"id":67,"mode":"scale","text":"ألاحظ غالبًا ما يشعر به الآخرون من نبرة الصوت، وتعبيرات الوجه، ولغة الجسد، حتى عندما لا يتحدثون عن مشاعرهم.","meta":{"indicator":"الذكاءات","dimension":"الاجتماعي"}},{"id":68,"mode":"scale","text":"عندما يثير موضوع دراسي اهتمامي، أبحث عنه خارج ما هو مطلوب في الكتاب أو الواجب لأعرف عنه بصورة أوسع.","meta":{"indicator":"الجدارات","dimension":"4. التعلم الذاتي"}},{"id":69,"mode":"scale","text":"عندما أسمع قراءة أو نشيدًا أو مقطعًا صوتيًا، ألاحظ بسرعة أي تغير أو خلل في النغمة أو الإيقاع.","meta":{"indicator":"الذكاءات","dimension":"السمعي"}},{"id":70,"mode":"scale","text":"إذا كان أمامي أكثر من خيار مهم، أقارن بين مزايا كل خيار ونتائجه المحتملة قبل أن أقرر أيها أنسب.","meta":{"indicator":"الجدارات","dimension":"5. حل المشكلات واتخاذ القرار"}},{"id":71,"mode":"scale","text":"أستطيع التعبير عن أفكاري ومشاعري من خلال الكتابة أو الحديث بطريقة واضحة ومؤثرة.","meta":{"indicator":"الذكاءات","dimension":"اللغوي"}},{"id":72,"mode":"scale","text":"عندما أشعر بالملل أو انخفاض الحماس أثناء مهمة مهمة، أواصل العمل عليها أو أعود إليها بعد فترة قصيرة بدلًا من تركها دون إكمال.","meta":{"indicator":"الجدارات","dimension":"1. إدارة الذات والانضباط"}},{"id":73,"mode":"scale","text":"أستطيع تخيّل الأشكال من زوايا مختلفة ومعرفة كيفية تجميع أجزائها؛ مثل تركيب جهاز أو مجسّم بالاستعانة بالرسم التوضيحي.","meta":{"indicator":"الذكاءات","dimension":"البصري"}},{"id":74,"mode":"scale","text":"عندما ألاحظ أنني تأخرت في إنجاز مهمة عن خطتي، أعيد ترتيب وقتي أو أولوياتي حتى أستطيع إنهاءها في موعدها.","meta":{"indicator":"الجدارات","dimension":"2. التخطيط وإدارة الوقت"}},{"id":75,"mode":"scale","text":"أستطيع استخدام يدي بمهارة لإنجاز المهام العملية؛ مثل تركيب جهاز، أو إصلاح عطل بسيط، أو صنع نموذج.","meta":{"indicator":"الذكاءات","dimension":"الحركي"}},{"id":76,"mode":"scale","text":"عندما أتعهد أمام معلم أو زملاء بإنجاز مهمة معينة، أتابعها حتى تكتمل ولا أعتمد على أن يتولى شخص آخر ما التزمت به.","meta":{"indicator":"الجدارات","dimension":"3. تحمل المسؤولية"}},{"id":77,"mode":"scale","text":"أستطيع تكوين علاقات مع أشخاص تختلف أعمارهم وشخصياتهم واهتماماتهم، وأكيّف طريقة تواصلي بما يناسب كل شخص.","meta":{"indicator":"الذكاءات","dimension":"الاجتماعي"}},{"id":78,"mode":"scale","text":"إذا واجهت موضوعًا أو مهارة جديدة، أبحث عن الطريقة والمصادر التي تساعدني على تعلمها بنفسي قبل الاعتماد الكامل على مساعدة الآخرين.","meta":{"indicator":"الجدارات","dimension":"4. التعلم الذاتي"}},{"id":79,"mode":"scale","text":"عندما لا تنجح محاولتي الأولى في حل مشكلة، أراجع ما حدث وأجرب طريقة مختلفة بدلًا من تكرار الأسلوب نفسه دون تغيير.","meta":{"indicator":"الجدارات","dimension":"5. حل المشكلات واتخاذ القرار"}},{"id":80,"mode":"scale","text":"أحدد أهدافي الشخصية بناءً على معرفتي بذاتي، وما أملكه من قدرات، وما يتوافق مع اهتماماتي وطموحاتي.","meta":{"indicator":"الذكاءات","dimension":"الذاتي"}},{"id":81,"mode":"scale","text":"إذا لم أفهم المطلوب في مهمة أو تعليمات، أطلب التوضيح في الوقت المناسب بدلًا من الاستمرار وأنا غير متأكد مما يجب فعله.","meta":{"indicator":"الجدارات","dimension":"6. التواصل الفعّال"}},{"id":82,"mode":"scale","text":"عندما نناقش قرارًا داخل الفريق، أشارك برأيي وأتقبل العمل برأي آخر إذا تبين أنه الأنسب لهدف الفريق.","meta":{"indicator":"الجدارات","dimension":"7. التعاون والعمل الجماعي"}},{"id":83,"mode":"scale","text":"أستطيع متابعة شرح شفهي يتضمن عدة أفكار، وفهم النقاط الرئيسة والعلاقة بينها دون الحاجة إلى رؤيتها مكتوبة.","meta":{"indicator":"الذكاءات","dimension":"السمعي"}},{"id":84,"mode":"scale","text":"عندما أواجه ضغطًا أو عدة متطلبات في وقت واحد، أحافظ على قدرتي على العمل وأعيد تنظيم أسلوبي بما يتناسب مع الظروف بدلًا من أن يعطلني الضغط.","meta":{"indicator":"الجدارات","dimension":"8. المرونة والتكيف"}}]};
